// @FIGURE_CODE_BEGIN
var RT_SERIF = '"Times New Roman", Times, serif';
var RT_BLUE = '#3f6ea8';
var RT_ACC = '#d9822b';
var RT_BAND = '#fdeacd';

var rtDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var RTW = 1080, RTH = 1500;
rtDraw.viewbox(0, 0, RTW, RTH).attr('preserveAspectRatio', 'xMidYMid meet');

var gStatic = rtDraw.group();
var gBand = rtDraw.group();
var gTree = rtDraw.group();
var gHi = rtDraw.group();

var rtState = { stage: 3, n: 16, overlay: false };
var rtStageNames = ['T(n)', 'one split', 'two splits', 'full tree'];

/* ---------- small helpers ---------- */
function mt(g, str, x, y, o) {
  o = o || {};
  var t = g.text(str).font({
    family: RT_SERIF, size: o.size || 28,
    style: o.normal ? 'normal' : 'italic', anchor: 'middle'
  }).fill(o.color || '#000');
  if (o.bold) t.font({ weight: 'bold' });
  t.center(x, y);
  return t;
}
function mix(g, parts, x, y, size, color, bold) {
  var t = g.text(function (add) {
    parts.forEach(function (p) {
      add.tspan(p[0]).font({ style: p[1] ? 'italic' : 'normal' });
    });
  }).font({ family: RT_SERIF, size: size, anchor: 'middle' }).fill(color || '#000');
  if (bold) t.font({ weight: 'bold' });
  t.center(x, y);
  return t;
}
function ln(g, x1, y1, x2, y2, o) {
  o = o || {};
  var l = g.line(x1, y1, x2, y2).stroke({
    color: o.color || '#000', width: o.width || 1.6, linecap: 'round'
  });
  if (o.dash) l.attr('stroke-dasharray', o.dash);
  return l;
}
function hook(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  if (title) el.on('click', function () { showPopup(title, body); });
}
function edge(g, px, py, cx, cy, o) {
  var s = cx > px ? 1 : -1;
  return ln(g, px + 14 * s, py + 16, cx - 6 * s, cy - 22, o);
}

/* ---------- geometry of panel (d) ---------- */
var R = { x: 437, y: 652 };
var L1X = [277, 600], Y1 = 840;
var L2X = [200, 348, 522, 668], Y2 = 1022;
var LEAFX = [152, 230, 308, 386, 464, 632, 712], YL = 1298;

/* ---------- static panels (a) (b) (c) ---------- */
function rtStatic() {
  var g = gStatic;
  // (a)
  var a = mt(g, 'T(n)', 48, 28, { color: RT_BLUE });
  hook(a, 'T(n): the unknown total cost', 'Panel (a): the starting point',
    'We begin with one unresolved quantity, T(n) — the time to merge-sort n elements. The recurrence T(n) = 2T(n/2) + cn is what lets us replace it with something we can count.');
  mt(g, '(a)', 48, 462, { normal: true });

  // (b)
  var b0 = mt(g, 'cn', 320, 28);
  edge(g, 320, 28, 250, 212); edge(g, 320, 28, 392, 212);
  var b1 = mt(g, 'T(n/2)', 250, 212, { color: RT_BLUE });
  var b2 = mt(g, 'T(n/2)', 392, 212, { color: RT_BLUE });
  [b1, b2].forEach(function (e) {
    hook(e, 'T(n/2): still unresolved', 'Panel (b): one application of the recurrence',
      'The divide-and-merge work at the top, cn, becomes a real cost node. What is left below are two identical subproblems of half the size.');
  });
  hook(b0, 'cn: merge cost of the top call', 'The cn term',
    'Splitting the array is cheap, but merging the two sorted halves touches every element once: that is the cn term of the recurrence.');
  mt(g, '(b)', 325, 462, { normal: true });

  // (c)
  var c0 = mt(g, 'cn', 790, 28);
  edge(g, 790, 28, 636, 214); edge(g, 790, 28, 950, 214);
  var c1 = mt(g, 'cn/2', 636, 214), c2 = mt(g, 'cn/2', 950, 214);
  edge(g, 636, 214, 560, 394); edge(g, 636, 214, 712, 394);
  edge(g, 950, 214, 886, 394); edge(g, 950, 214, 1026, 394);
  [[560], [712], [886], [1026]].forEach(function (p) {
    var t = mt(g, 'T(n/4)', p[0], 394, { color: RT_BLUE });
    hook(t, 'T(n/4): unresolved, quarter size', 'Panel (c): expand once more',
      'Every T(n/2) is replaced the same way: a cn/2 cost node plus two T(n/4) children. The rule never changes — only the size does.');
  });
  [c1, c2].forEach(function (e) {
    hook(e, 'cn/2: merge cost of a half-size call', 'Half the input, half the merge',
      'A subproblem of size n/2 costs c·(n/2) to merge. There are two of them, so this level still costs 2 × cn/2 = cn.');
  });
  hook(c0, 'cn: merge cost of the top call', 'The cn term', 'The root cost never changes as we expand deeper: it is always cn.');
  mt(g, '(c)', 800, 462, { normal: true });

  // governing recurrence
  mix(g, [['T', 1], ['(', 0], ['n', 1], [') = 2', 0], ['T', 1], ['(', 0], ['n', 1], ['/2) + ', 0], ['cn', 1]],
    540, 556, 24, '#555');

  // panel (d) letter
  mt(g, '(d)', 437, 1452, { normal: true });
}

/* ---------- decorations ---------- */
function arrowUp(g, x, y) { g.polygon(x + ',' + (y - 16) + ' ' + (x - 9) + ',' + (y + 6) + ' ' + (x + 9) + ',' + (y + 6)).fill('#000'); }
function arrowDown(g, x, y) { g.polygon(x + ',' + (y + 16) + ' ' + (x - 9) + ',' + (y - 6) + ' ' + (x + 9) + ',' + (y - 6)).fill('#000'); }

function bracePath(x1, x2, y, d) {
  var mid = (x1 + x2) / 2;
  return 'M' + x1 + ',' + y + ' q0,' + d + ' ' + d + ',' + d +
    ' L' + (mid - d) + ',' + (y + d) + ' q' + d + ',0 ' + d + ',' + d +
    ' q0,' + (-d) + ' ' + d + ',' + (-d) +
    ' L' + (x2 - d) + ',' + (y + d) + ' q' + d + ',0 ' + d + ',' + (-d);
}

/* ---------- right-hand cost column ---------- */
function rtRightColumn(rows, showEllipsis) {
  rows.forEach(function (r) {
    var on = rtState.overlay;
    ln(gTree, r.sx, r.y, 826, r.y, {
      dash: '1.5,5', width: on ? 3 : 2.4, color: on ? RT_ACC : '#000'
    });
    gTree.polygon('830,' + (r.y - 6) + ' 846,' + r.y + ' 830,' + (r.y + 6))
      .fill(on ? RT_ACC : '#000');
    var lab = mt(gTree, 'cn', 878, r.y, { color: on ? RT_ACC : '#000', bold: on });
    hook(lab, r.expr + ' = cn', 'This level costs cn',
      'There are ' + r.count + ' node(s) on this level and each costs ' + r.each +
      '. Multiply: ' + r.expr + ' = cn. Node count doubles exactly as node cost halves, so every level sums to the same cn.');
    if (on) mt(gTree, r.expr, 985, r.y, { size: 18, color: RT_ACC });
  });
  if (showEllipsis) {
    [1140, 1168, 1196].forEach(function (yy) { gTree.circle(6).center(878, yy).fill('#000'); });
  }
}

/* ---------- main render ---------- */
function rtRender() {
  gBand.clear(); gTree.clear(); gHi.clear();
  var st = rtState.stage, lg = Math.round(Math.log(rtState.n) / Math.LN2);
  var rows = [];

  if (st === 0) {
    var t0 = mt(gTree, 'T(n)', R.x, R.y, { color: RT_BLUE, size: 32 });
    hook(t0, 'T(n): unresolved total cost', 'Step 1 — nothing resolved yet',
      'All of the work is hidden inside a single symbol. Press "Expand recursion" to apply T(n) = 2T(n/2) + cn.');
  } else {
    var root = mt(gTree, 'cn', R.x, R.y);
    hook(root, 'cn: merge cost at the root', 'Level 0 costs cn',
      'The top-level call merges two sorted halves of a size-n array, which costs cn. All the rest of the work lives in the two children.');
    rows.push({ y: R.y, sx: 480, expr: '1 × cn', count: 1, each: 'cn' });

    L1X.forEach(function (x) { edge(gTree, R.x, R.y, x, Y1); });
    if (st === 1) {
      L1X.forEach(function (x) {
        var e = mt(gTree, 'T(n/2)', x, Y1, { color: RT_BLUE });
        hook(e, 'T(n/2): unresolved subproblem', 'Two half-size subproblems',
          'The recurrence says the remaining work is exactly two independent sorts of n/2 elements. Expand again to turn each into its own cost node.');
      });
    } else {
      L1X.forEach(function (x) {
        var e = mt(gTree, 'cn/2', x, Y1);
        hook(e, 'cn/2: merge cost of an n/2 call', 'Level 1 costs 2 × cn/2 = cn',
          'Each of the two nodes costs half as much as the root, but there are twice as many — so the level total is unchanged at cn.');
      });
      rows.push({ y: Y1, sx: 650, expr: '2 × cn/2', count: 2, each: 'cn/2' });
      L1X.forEach(function (px, i) {
        edge(gTree, px, Y1, L2X[2 * i], Y2);
        edge(gTree, px, Y1, L2X[2 * i + 1], Y2);
      });
      if (st === 2) {
        L2X.forEach(function (x) {
          var e = mt(gTree, 'T(n/4)', x, Y2, { color: RT_BLUE });
          hook(e, 'T(n/4): unresolved subproblem', 'Four quarter-size subproblems',
            'Four unknowns of size n/4 remain. Keep expanding and the pattern continues until the subproblems have size 1.');
        });
      } else {
        L2X.forEach(function (x) {
          var e = mt(gTree, 'cn/4', x, Y2);
          hook(e, 'cn/4: merge cost of an n/4 call', 'Level 2 costs 4 × cn/4 = cn',
            'Four nodes, each a quarter of the root cost: 4 × cn/4 = cn again. This is the pattern that makes the sum easy.');
        });
        rows.push({ y: Y2, sx: 718, expr: '4 × cn/4', count: 4, each: 'cn/4' });

        // omitted levels: short solid edges + dashes
        L2X.forEach(function (x) {
          [-1, 1].forEach(function (s) {
            ln(gTree, x + 10 * s, Y2 + 16, x + 34 * s, Y2 + 106);
            ln(gTree, x + 36 * s, Y2 + 112, x + 44 * s, Y2 + 142, { dash: '7,7' });
          });
        });
        // vertical dotted continuations
        LEAFX.forEach(function (x) { ln(gTree, x, 1226, x, 1274, { dash: '2,10', width: 2 }); });

        // leaf row
        LEAFX.forEach(function (x) {
          var e = mt(gTree, 'c', x, YL);
          hook(e, 'c: cost of a size-1 subproblem', 'The leaves',
            'A subproblem of size 1 is already sorted, so it costs a constant c. There are n such leaves, giving n × c = cn for the bottom row.');
        });
        mt(gTree, '· · ·', 548, YL - 4, { normal: true, size: 26 });
        rows.push({ y: YL, sx: 758, expr: 'n × c', count: 'n', each: 'c' });

        // brace + n
        gTree.path(bracePath(120, 745, 1326, 16)).fill('none').stroke({ color: '#000', width: 1.6 });
        var nlab = mt(gTree, 'n', 437, 1392);
        hook(nlab, 'n leaves at the bottom', 'Why n leaves?',
          'Halving the subproblem size until it reaches 1 produces exactly n leaves. Their total cost is cn — the same as every other level.');
        if (rtState.overlay || rtState.n !== 16) {
          mt(gTree, 'n = ' + rtState.n + ' leaves', 437, 1422, { size: 18, color: RT_ACC });
        }

        // height arrow
        ln(gTree, 72, 655, 72, 1300, { width: 2 });
        arrowUp(gTree, 72, 655); arrowDown(gTree, 72, 1300);
        var hl = mix(gTree, [['lg', 0], [' ', 0], ['n', 1]], 34, 975, 28, '#000');
        hook(hl, 'Tree height = lg n', 'Counting the levels',
          'Each level halves the subproblem size, so it takes lg n halvings to reach size 1. Including the root level there are lg n + 1 rows, each costing cn.');
        if (rtState.overlay || rtState.n !== 16) {
          mt(gTree, 'lg ' + rtState.n + ' = ' + lg, 34, 1008, { size: 18, color: RT_ACC });
        }

        // total rule + text
        ln(gTree, 812, 1350, 936, 1350, { width: 1.8 });
        var tot = mix(gTree, [['Total: ', 0], ['cn', 1], [' ', 0], ['lg', 0], [' ', 0], ['n', 1], [' + ', 0], ['cn', 1]],
          868, 1400, 28, rtState.overlay ? RT_ACC : '#000', rtState.overlay);
        hook(tot, 'cn lg n + cn = Θ(n lg n)', 'Adding it all up',
          'There are lg n + 1 levels and each one costs exactly cn. So the total is cn(lg n + 1) = cn lg n + cn, i.e. Θ(n lg n) — far better than the Θ(n²) of insertion sort.');
        if (rtState.overlay) {
          mt(gTree, '(lg ' + rtState.n + ' + 1) = ' + (lg + 1) + ' rows × cn', 868, 1442,
            { size: 18, color: RT_ACC, normal: true });
        }
      }
    }
  }

  // level-cost bands
  if (rtState.overlay) {
    rows.forEach(function (r) {
      gBand.rect(700, 50).move(102, r.y - 25).radius(6).fill(RT_BAND).opacity(0.85);
    });
  }

  // right column (always at full tree, else only with overlay)
  if (st === 3 || (rtState.overlay && rows.length)) rtRightColumn(rows, st === 3);

  // stage highlight on panels a/b/c
  if (st < 3) {
    var reg = [[8, 6, 176, 478], [196, 6, 300, 478], [508, 6, 566, 478]][st];
    gHi.rect(reg[2], reg[3]).move(reg[0], reg[1]).radius(8)
      .fill({ color: RT_ACC, opacity: 0.05 })
      .stroke({ color: RT_ACC, width: 1.5, dasharray: '7,5' });
  }
}

/* ---------- interactions ---------- */
function rtSyncUI() {
  document.getElementById('stageLabel').textContent = 'showing: ' + rtStageNames[rtState.stage];
  document.getElementById('problemSizeVal').value = rtState.n;
  document.getElementById('problemSizeInput').value = Math.round(Math.log(rtState.n) / Math.LN2);
  document.getElementById('levelCostsInput').checked = rtState.overlay;
}
function trigger_expandStage() {
  rtState.stage = (rtState.stage + 1) % 4;
  rtSyncUI(); rtRender();
}
function update_problemSize(v) {
